+        path: paths.rejectedDeltaOut,
+        assertion_count: layers.rejected.length,
+      },
+      blocked_quarantined: {
+        path: paths.blockedQuarantinedDeltaOut,
+        assertion_count: layers.blockedQuarantined.length,
+      },
+    },
+    promoted_assertion_ids: {
+      accepted: layers.accepted.map((item) => item.source_assertion_id),
+      provisional_safe: layers.provisionalSafe.map((item) => item.source_assertion_id),
+    },
+    raw_candidate_exclusion_proof: rawCandidateExclusionProof,
+    validator_backed_deferral: validatorBackedDeferral,
+    validator_backed_review_deferral: validatorBackedReviewDeferral,
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        summary,
+        accepted: layers.accepted.map((item) => item.source_assertion_id),
+        provisional_safe: layers.provisionalSafe.map((item) => item.source_assertion_id),
+        review_required: layers.reviewRequired.map((item) => item.source_assertion_id),
+        rejected: layers.rejected.map((item) => item.source_assertion_id),
+        blocked_quarantined: layers.blockedQuarantined.map((item) => item.source_assertion_id),
+      }),
+    },
+  };
+}
+
+function buildLayerDelta({ layerName, generatedAt, promotionRunPath, assertions }) {
+  return {
+    schema_version: `semantic_kg_wave1_${layerName}_layer_delta.v1`,
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    source_promotion_run_path: promotionRunPath,
+    layer: layerName,
+    summary: {
+      assertion_count: assertions.length,
+      by_predicate: countBy(assertions, 'predicate'),
+      by_question: countBy(assertions, 'question_row_id'),
+      by_topic_component_group: countBy(assertions, 'topic_component_group'),
+      by_risk_tier: countBy(assertions, 'risk_tier'),
+      by_evidence_family: countEvidenceFamilies(assertions),
+      external_model_call_count: 0,
+    },
+    assertions,
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        layerName,
+        assertions: assertions.map((item) => item.source_assertion_id),
+      }),
+    },
+  };
+}
+
+function ragManifestItem(item, consumptionPosture) {
+  return {
+    assertion_id: item.source_assertion_id,
+    predicate: item.predicate,
+    question_row_id: item.question_row_id,
+    topic_component_group: item.topic_component_group,
+    risk_tier: item.risk_tier,
+    source_shard_id: item.source_shard_id,
+    source_status_before_promotion: item.source_status_before_promotion,
+    subject_ref: item.subject_ref,
+    object_ref: item.object_ref,
+    scope_ref: item.scope_ref,
+    evidence_refs: item.evidence_refs,
+    provenance: item.provenance,
+    consumption_posture: consumptionPosture,
+  };
+}
+
+function buildRagConsumptionManifest({ generatedAt, promotionRun, layers, rawCandidateCount }) {
+  const acceptedItems = layers.accepted.map((item) => ragManifestItem(item, 'rag_answer_fact'));
+  const provisionalItems = layers.provisionalSafe.map((item) => ragManifestItem(
+    item,
+    'downgraded_context_not_answer_fact',
+  ));
+  const unsafeItemCount =
+    rawCandidateCount +
+    layers.reviewRequired.length +
+    layers.rejected.length +
+    layers.blockedQuarantined.length;
+  const totalItems = acceptedItems.length + provisionalItems.length + unsafeItemCount;
+  const candidateOnlyRatio = totalItems > 0 ? rawCandidateCount / totalItems : 0;
+  const acceptedCountRequired =
+    promotionRun.threshold_context.threshold_values.accepted_count_required_for_rag_manifest;
+  const maxCandidateOnlyRatio =
+    promotionRun.threshold_context.threshold_values.max_candidate_only_ratio_for_rag_manifest;
+  const acceptedCountThresholdMet = acceptedItems.length >= acceptedCountRequired;
+  const acceptedDeferralActive = promotionRun.validator_backed_deferral?.active === true;
+  const reviewDeferralActive = promotionRun.validator_backed_review_deferral?.active === true;
+  const manifestStatus = acceptedDeferralActive && reviewDeferralActive
+    ? 'rag_ready_with_accepted_growth_and_review_deferral'
+    : acceptedDeferralActive
+      ? 'rag_ready_with_accepted_growth_deferral'
+      : reviewDeferralActive
+        ? 'rag_ready_with_review_deferral'
+        : acceptedCountThresholdMet && candidateOnlyRatio <= maxCandidateOnlyRatio
+          ? 'rag_ready'
+          : 'not_ready_threshold_failed';
+
+  return {
+    schema_version: 'semantic_kg_wave1_rag_consumption_manifest.v1',
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    consumer: 'RAG-LITE-HVY',
+    manifest_status: manifestStatus,
+    semantic_context_status: promotionRun.validator_backed_deferral?.active === true
+      ? 'provisional_degraded'
+      : 'available',
+    source_promotion_run_path: promotionRun.output_artifacts.promotion_run,
+    summary: {
+      accepted_fact_count: acceptedItems.length,
+      provisional_downgraded_context_count: provisionalItems.length,
+      raw_candidate_item_count: rawCandidateCount,
+      review_required_item_count: layers.reviewRequired.length,
+      rejected_item_count: layers.rejected.length,
+      blocked_quarantined_item_count: layers.blockedQuarantined.length,
+      candidate_only_ratio: candidateOnlyRatio,
+      accepted_count_threshold_met: acceptedCountThresholdMet,
+      accepted_growth_deferral_active: acceptedDeferralActive,
+      review_queue_deferral_active: reviewDeferralActive,
+      accepted_and_provisional_counts_separated: true,
+      unsafe_layers_excluded_from_answer_facts: true,
+      production_rag_reindex_performed: false,
+      vector_store_mutation_performed: false,
+      remote_supabase_mutation_performed: false,
+    },
+    answer_policy: {
+      answer_fact_layers: ['accepted'],
+      downgraded_context_layers: ['provisional_safe'],
+      excluded_answer_fact_layers: [...UNSAFE_LAYERS],
+      fallback_behavior:
+        'If accepted facts do not cover the answer need, RAG-LITE must fall back to question text, runtime evidence, and Method posture without inventing concept, skill, or procedure facts from provisional/unsafe layers.',
+    },
+    layers: {
+      accepted_facts: {
+        assertion_count: acceptedItems.length,
+        source_delta_path: promotionRun.output_artifacts.accepted_delta,
+        consumption_posture: 'rag_answer_fact',
+        items: acceptedItems,
+      },
+      provisional_downgraded_context: {
+        assertion_count: provisionalItems.length,
+        source_delta_path: promotionRun.output_artifacts.provisional_safe_delta,
+        consumption_posture: 'downgraded_context_not_answer_fact',
+        items: provisionalItems,
+      },
+      excluded_from_answer_facts: {
+        raw_candidate: {
+          item_count: rawCandidateCount,
+          source_assertion_ids:
+            promotionRun.raw_candidate_exclusion_proof.source_raw_candidate_assertion_ids,
+        },
+        review_required: {
+          item_count: layers.reviewRequired.length,
+          source_delta_path: promotionRun.output_artifacts.review_required_delta,
+          source_assertion_ids: layers.reviewRequired.map((item) => item.source_assertion_id),
+        },
+        rejected: {
+          item_count: layers.rejected.length,
+          source_delta_path: promotionRun.output_artifacts.rejected_delta,
+          source_assertion_ids: layers.rejected.map((item) => item.source_assertion_id),
+        },
+        blocked_quarantined: {
+          item_count: layers.blockedQuarantined.length,
+          source_delta_path: promotionRun.output_artifacts.blocked_quarantined_delta,
+          source_assertion_ids: layers.blockedQuarantined.map((item) => item.source_assertion_id),
+        },
+      },
+    },
+    exclusion_proofs: {
+      raw_candidates_excluded: promotionRun.raw_candidate_exclusion_proof,
+      raw_review_blocked_rejected_excluded_from_answer_facts: true,
+    },
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        accepted: acceptedItems.map((item) => item.assertion_id),
+        provisional: provisionalItems.map((item) => item.assertion_id),
+        manifestStatus,
+      }),
+    },
+  };
+}
+
+function passCheck(id, evidence = {}) {
+  return { id, status: 'pass', evidence };
+}
+
+function failCheck(id, reason, evidence = {}) {
+  return { id, status: 'fail', reason, evidence };
+}
+
+function blockedCheck(id, reason, evidence = {}) {
+  return { id, status: 'blocked', reason, evidence };
+}
+
+function promotedHasEvidenceAndProvenance(item) {
+  return isObject(item?.provenance) &&
+    Array.isArray(item?.evidence_refs) &&
+    item.evidence_refs.length > 0 &&
+    isObject(item.provenance.source_shard_assertion_ref) &&
+    isObject(item.provenance.threshold_artifact_ref);
+}
+
+function requiredCountDimensionsPresent(counts) {
+  return ['by_predicate', 'by_question', 'by_topic_component_group', 'by_risk_tier', 'by_evidence_family']
+    .every((field) => isObject(counts.accepted[field]) && isObject(counts.provisional_safe[field]));
+}
+
+function validatePromotion({
+  promotionRun,
+  layers,
+  ragConsumptionManifest,
+  inputs,
+  inputDiagnostics,
+}) {
+  const diagnostics = Array.isArray(inputDiagnostics) ? inputDiagnostics.filter(isObject) : [];
+  const criticalDiagnostics = diagnostics.filter((diagnostic) => diagnostic.severity === 'critical');
+  const promoted = [...layers.accepted, ...layers.provisionalSafe];
+  const summary = promotionRun.summary;
+  const thresholdValues = promotionRun.threshold_context.threshold_values;
+  const reviewLoadThresholdsValid =
+    Number.isFinite(thresholdValues.max_review_required_per_question) &&
+    Number.isFinite(thresholdValues.max_review_required_ratio);
+  const candidateOnlyRatioThresholdValid =
+    Number.isFinite(thresholdValues.max_candidate_only_ratio_for_rag_manifest);
+  const representedSurfaceThresholdsValid =
+    Number.isFinite(thresholdValues.min_predicates_represented_for_launch_slice) &&
+    Number.isFinite(thresholdValues.min_topic_component_groups_for_launch_slice);
+
+  const checks = [
+    summary.accepted_count > 0
+      ? passCheck('accepted_count_positive', {
+        accepted_count: summary.accepted_count,
+        accepted_question_count: summary.accepted_question_count,
+      })
+      : blockedCheck('accepted_count_positive', 'validator_backed_zero_accepted_blocker_required', {
+        accepted_count: summary.accepted_count,
+      }),
+    summary.accepted_wave1_threshold_met === true &&
+      summary.accepted_growth_positive_against_1367 === true
+      ? passCheck('wave1_accepted_growth_and_threshold', {
+        accepted_count: summary.accepted_count,
+        accepted_growth_against_1367: summary.accepted_growth_against_1367,
+      })
+      : blockedCheck('wave1_accepted_growth_and_threshold', 'validator_backed_deferral_active', {
+        deferral: promotionRun.validator_backed_deferral,
+      }),
+    ragConsumptionManifest.summary.accepted_fact_count === summary.accepted_count &&
+      ragConsumptionManifest.summary.provisional_downgraded_context_count === summary.provisional_safe_count &&
+      ragConsumptionManifest.summary.accepted_and_provisional_counts_separated === true
+      ? passCheck('accepted_provisional_counts_reported_separately_in_rag_manifest', {
+        accepted_count: ragConsumptionManifest.summary.accepted_fact_count,
+        provisional_safe_count: ragConsumptionManifest.summary.provisional_downgraded_context_count,
+      })
+      : failCheck('accepted_provisional_counts_reported_separately_in_rag_manifest', 'rag_manifest_counts_not_separated'),
+    criticalDiagnostics.length === 0 &&
+      inputs.thresholds?.issue === 1366 &&
+      inputs.baselinePromotion?.issue === 1367 &&
+      inputs.wave1Summary?.issue === 1368 &&
+      validatorStatus(inputs.thresholdsValidator) === 'pass' &&
+      validatorStatus(inputs.wave1Validator) === 'pass'
+      ? passCheck('wave1_inputs_loaded_and_validated', {
+        thresholds_issue: inputs.thresholds?.issue,
+        baseline_issue: inputs.baselinePromotion?.issue,
+        wave1_issue: inputs.wave1Summary?.issue,
+      })
+      : failCheck('wave1_inputs_loaded_and_validated', 'input_or_validator_not_pass', {
+        critical_diagnostics: criticalDiagnostics,
+        thresholds_issue: inputs.thresholds?.issue ?? null,
+        baseline_issue: inputs.baselinePromotion?.issue ?? null,
+        wave1_issue: inputs.wave1Summary?.issue ?? null,
+        thresholds_validator_status: validatorStatus(inputs.thresholdsValidator),
+        wave1_validator_status: validatorStatus(inputs.wave1Validator),
+      }),
+    requiredCountDimensionsPresent(promotionRun.counts)
+      ? passCheck('count_breakdowns_cover_required_dimensions', {
+        accepted_dimensions: Object.keys(promotionRun.counts.accepted),
+        provisional_safe_dimensions: Object.keys(promotionRun.counts.provisional_safe),
+      })
+      : failCheck('count_breakdowns_cover_required_dimensions', 'required_count_dimension_missing'),
+    summary.high_risk_accepted_count === 0
+      ? passCheck('high_risk_assertions_not_auto_accepted', { high_risk_accepted_count: 0 })
+      : failCheck('high_risk_assertions_not_auto_accepted', 'high_risk_assertion_accepted'),
+    summary.layer_entry_count === summary.source_assertion_count
+      ? passCheck('layer_count_conservation', {
+        source_assertion_count: summary.source_assertion_count,
+        layer_entry_count: summary.layer_entry_count,
+      })
+      : failCheck('layer_count_conservation', 'layer_entries_do_not_match_source_assertion_count'),
+    summary.external_model_call_count === 0 &&
+      summary.production_rag_reindex_count === 0 &&
+      summary.vector_store_mutation_count === 0 &&
+      summary.remote_supabase_mutation_performed === false
+      ? passCheck('no_external_or_runtime_side_effects', {
+        external_model_call_count: 0,
+        production_rag_reindex_count: 0,
+        vector_store_mutation_count: 0,
+      })
+      : failCheck('no_external_or_runtime_side_effects', 'side_effect_counter_nonzero'),
+    promoted.every((item) => promotedHasEvidenceAndProvenance(item))
+      ? passCheck('promoted_assertions_have_evidence_and_provenance', {
+        promoted_count: promoted.length,
+      })
+      : failCheck('promoted_assertions_have_evidence_and_provenance', 'promoted_assertion_missing_evidence_or_provenance', {
+        assertion_ids: promoted
+          .filter((item) => !promotedHasEvidenceAndProvenance(item))
+          .map((item) => item.source_assertion_id),
+      }),
+    candidateOnlyRatioThresholdValid &&
+      ragConsumptionManifest.summary.candidate_only_ratio <= thresholdValues.max_candidate_only_ratio_for_rag_manifest
