+        candidate_only_ratio: ragConsumptionManifest.summary.candidate_only_ratio,
+        threshold: thresholdValues.max_candidate_only_ratio_for_rag_manifest,
+      })
+      : failCheck('rag_manifest_candidate_only_ratio_within_threshold', 'candidate_only_ratio_threshold_missing_or_exceeded'),
+    ragConsumptionManifest.layers.accepted_facts.items.length === summary.accepted_count &&
+      ragConsumptionManifest.layers.provisional_downgraded_context.items.every((item) => (
+        item.consumption_posture === 'downgraded_context_not_answer_fact'
+      )) &&
+      ragConsumptionManifest.summary.unsafe_layers_excluded_from_answer_facts === true
+      ? passCheck('rag_answer_facts_exclude_unsafe_layers', {
+        accepted_fact_count: ragConsumptionManifest.layers.accepted_facts.items.length,
+        unsafe_excluded_count:
+          ragConsumptionManifest.summary.raw_candidate_item_count +
+          ragConsumptionManifest.summary.review_required_item_count +
+          ragConsumptionManifest.summary.rejected_item_count +
+          ragConsumptionManifest.summary.blocked_quarantined_item_count,
+      })
+      : failCheck('rag_answer_facts_exclude_unsafe_layers', 'unsafe_layer_available_as_answer_fact'),
+    promotionRun.raw_candidate_exclusion_proof.intersection_count === 0 &&
+      promoted.every((item) => item.raw_candidate_payload_included === false)
+      ? passCheck('raw_candidates_excluded_from_promoted_layers', {
+        raw_promoted_intersection_count: 0,
+      })
+      : failCheck('raw_candidates_excluded_from_promoted_layers', 'raw_candidate_promoted'),
+    reviewLoadThresholdsValid &&
+      summary.review_required_per_question <= thresholdValues.max_review_required_per_question &&
+      summary.review_required_ratio <= thresholdValues.max_review_required_ratio
+      ? passCheck('review_load_within_threshold_budget', {
+        review_required_per_question: summary.review_required_per_question,
+        review_required_ratio: summary.review_required_ratio,
+      })
+      : promotionRun.validator_backed_review_deferral?.active === true
+        ? blockedCheck('review_load_within_threshold_budget', 'validator_backed_review_deferral_active', {
+          deferral: promotionRun.validator_backed_review_deferral,
+        })
+        : failCheck('review_load_within_threshold_budget', 'review_load_threshold_exceeded'),
+    representedSurfaceThresholdsValid &&
+      summary.represented_predicates.length >= thresholdValues.min_predicates_represented_for_launch_slice &&
+      summary.topic_component_groups.length >= thresholdValues.min_topic_component_groups_for_launch_slice
+      ? passCheck('launch_slice_predicate_topic_thresholds', {
+        represented_predicate_count: summary.represented_predicates.length,
+        topic_component_group_count: summary.topic_component_groups.length,
+      })
+      : failCheck('launch_slice_predicate_topic_thresholds', 'launch_slice_surface_threshold_missing_or_not_met'),
