+  const failCount = checks.filter((check) => check.status === 'fail').length;
+  const blockedCount = checks.filter((check) => check.status === 'blocked').length;
+  const validationStatus = failCount > 0 ? 'fail' : blockedCount > 0 ? 'blocked' : 'pass';
+  return {
+    schema_version: 'semantic_kg_wave1_promotion_validator_result.v1',
+    generated_at: promotionRun.generated_at,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    validator_status: validationStatus,
+    promotion_run_path: promotionRun.output_artifacts.promotion_run,
+    rag_consumption_manifest_path: promotionRun.output_artifacts.rag_consumption_manifest,
+    summary: {
+      validation_status: validationStatus,
+      check_count: checks.length,
+      check_pass_count: checks.filter((check) => check.status === 'pass').length,
+      check_blocked_count: blockedCount,
+      check_fail_count: failCount,
+      accepted_count: summary.accepted_count,
+      provisional_safe_count: summary.provisional_safe_count,
+      review_required_count: summary.review_required_count,
+      rejected_count: summary.rejected_count,
+      blocked_quarantined_count: summary.blocked_quarantined_count,
+      covered_question_count: summary.covered_question_count,
+      accepted_growth_against_1367: summary.accepted_growth_against_1367,
+      provisional_safe_growth_against_1367: summary.provisional_safe_growth_against_1367,
+      represented_predicates: summary.represented_predicates,
+      topic_component_groups: summary.topic_component_groups,
+      rag_manifest_status: ragConsumptionManifest.manifest_status,
+      validator_backed_deferral_active: promotionRun.validator_backed_deferral?.active === true,
+      validator_backed_review_deferral_active:
+        promotionRun.validator_backed_review_deferral?.active === true,
+    },
+    checks,
+    input_diagnostics: diagnostics,
+  };
+}
